{
  "name": "一维连续扫描组件",
  "name_en": "1D Slew Scan Component",
  "manufacturer": "",
  "description": "用于实验扫描流程的非物理软件组件，负责执行一维连续扫描、准备与收尾扫描步骤、检查束流状态、解析 gathering 文本中的位置数据，并保存环境数据。它适用于基于 EPICS 的束线或实验站快速扫描数据采集流程。",
  "description_en": "A non-physical software component for experimental scan workflows. It performs 1D slew scans, handles scan preparation and cleanup, checks beam status, parses position data from gathering text, and saves environmental data. It is suited to EPICS-based beamline or laboratory fast-scan data acquisition workflows.",
  "actions": [
    {
      "action_name": "auto-prepare_scan",
      "description": "准备一维连续扫描流程。",
      "description_en": "Prepare the 1D slew scan workflow."
    },
    {
      "action_name": "auto-post_scan",
      "description": "执行扫描结束后的收尾处理。",
      "description_en": "Perform post-scan cleanup steps."
    },
    {
      "action_name": "auto-run",
      "description": "运行一维连续扫描并采集、整理扫描数据。",
      "description_en": "Run the 1D slew scan and acquire and organize scan data."
    },
    {
      "action_name": "auto-gathering2xvals",
      "description": "解析 gathering 文本并计算能量与高度数据。",
      "description_en": "Parse gathering text and calculate energy and height data."
    },
    {
      "action_name": "auto-check_beam_ok",
      "description": "检查束流状态是否正常。",
      "description_en": "Check whether the beam status is acceptable."
    },
    {
      "action_name": "auto-save_envdata",
      "description": "将环境数据保存到文件。",
      "description_en": "Save environmental data to a file."
    }
  ],
  "tag_hints": [
    "slew scan",
    "1D scanning",
    "EPICS scan control",
    "beamline data acquisition",
    "beam status check",
    "environment data logging",
    "fast scan workflow"
  ]
}

